void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy; // Normalized pixel coordinates (from 0 to 1)
    vec2 pxSize = vec2(8., 8.0);  
    vec2 nmPxSize = pxSize/ iResolution.xy; 
    vec2 uvPixel = nmPxSize*floor(uv/nmPxSize);
    vec4 color = texture(iChannel0,uvPixel);

    float luma = dot(vec3(0.2126, 0.7152, 0.0722), color.rgb);
    vec2 cellUV = fract(uv/nmPxSize);
    float lnWidth = .0;

    if(luma>0.0){lnWidth = 1.;}
    if(luma>0.3){lnWidth = .7;}
    if(luma>0.5){lnWidth = .5;}
    if(luma>0.7){lnWidth = .3;}
    if(luma>0.9){lnWidth = .1;}
    if(luma>0.99){lnWidth =.0;}

    float yStart = .05;
    float yEnd = .95;

    if(cellUV.y > yStart && cellUV.y < yEnd && cellUV.x > 0.0 && cellUV.x < lnWidth)
    {
        color = vec4(.0,.0,.0,1.);
    }
    else
    {
        color = vec4(.7,.74,.73, 1.);  
    }
    fragColor=color;  // Output to screen
}
